  function imageGenerator(cfg){const first=cfg.models[0],ratio=cfg.controls[0][1][0];return '<section class="photo-generator"><input id="knowledgeFile" type="file" accept="image/*" hidden><div class="photo-media-row"><div class="media-preview" id="mediaPreview" hidden><img alt=""><button type="button" data-remove-media aria-label="Удалить изображение">×</button></div><button class="photo-add" type="button" data-add-file aria-label="Добавить изображение">＋</button></div><div class="photo-prompt-wrap"><textarea id="knowledgePrompt" rows="3" aria-label="Описание изображения"></textarea><span class="photo-animated-placeholder" id="photoAnimatedPlaceholder" aria-hidden="true"></span></div><div class="photo-controls"><div class="photo-picker photo-model"><input id="knowledgeModel" type="hidden" value="'+first[0]+'"><button type="button" class="photo-picker-trigger" data-picker="model" aria-expanded="false">'+modelLogo(first[0])+'<b>'+first[1]+'</b><i>⌄</i></button><div class="photo-picker-menu model-menu" data-menu="model" hidden>'+cfg.models.map((m,i)=>'<button type="button" data-model="'+m[0]+'" data-label="'+esc(m[1])+'"'+(i===0?' class="is-selected"':'')+'>'+modelLogo(m[0])+'<span>'+esc(m[1])+'</span><i>✓</i></button>').join('')+'</div></div><div class="photo-picker photo-ratio"><input id="knowledgeRatio" type="hidden" value="'+ratio+'"><button type="button" class="photo-picker-trigger" data-picker="ratio" aria-expanded="false">'+ratioIcon(ratio)+'<b>'+ratio+'</b><i>⌄</i></button><div class="photo-picker-menu ratio-menu" data-menu="ratio" hidden>'+cfg.controls[0][1].map((v,i)=>'<button type="button" data-ratio="'+v+'" data-label="'+v+'"'+(i===0?' class="is-selected"':'')+'>'+ratioIcon(v)+'<span>'+v+'</span><i>✓</i></button>').join('')+'</div></div><button class="photo-generate" type="button" data-generate disabled>Сгенерировать</button></div></section>'}
  function generator(cfg){const top=mode==='music'?'<div class="quick-mode-label">Создайте новый трек</div><div class="qm-ref-row" id="qmRefRow" hidden><input id="qmRefFile" type="file" accept="audio/*" hidden><button type="button" class="qm-ref-add" data-qm-ref-add>＋ Аудио-референс</button><span class="qm-ref-chip" id="qmRefChip" hidden></span></div>':mode==='text'?'<div class="text-file-preview"><div class="media-preview" id="mediaPreview" hidden><img alt=""><button type="button" data-remove-media aria-label="Удалить файл">×</button></div></div>':'<div class="photo-media-row"><div class="media-preview" id="mediaPreview" hidden><img alt=""><button type="button" data-remove-media aria-label="Удалить файл">×</button></div><button class="photo-add" type="button" data-add-file aria-label="Добавить файл">＋</button></div>';const controls=mode==='text'?quickTextComposerControls():quickPicker('model',cfg.models,true)+cfg.controls.map(x=>quickPicker(x[0],x[1],false)).join('')+'<button class="photo-generate" type="button" data-generate disabled>Сгенерировать</button>';return '<section class="photo-generator quick-generator"><input id="knowledgeFile" type="file" accept="image/*" hidden>'+top+'<div class="photo-prompt-wrap"><textarea id="knowledgePrompt" rows="3" aria-label="Текст запроса"></textarea><span class="photo-animated-placeholder" id="photoAnimatedPlaceholder" aria-hidden="true"></span></div><div class="photo-controls quick-generator-controls">'+controls+'</div></section>'}
