  function catalogLane(title,items,kind){return '<section class="quick-catalog-group"><h3>'+title+'</h3><div class="quick-catalog-lane">'+items.map(item=>kind==='video'?'<button class="reference" data-template-id="'+item+'" data-ref="Видео-референс"><img loading="lazy" src="assets/video-templates/'+item+'/poster.jpg" alt=""><span>Открыть</span></button>':'<button class="reference" data-style="'+esc(item.split('/').pop().replace(/\.[^.]+$/,''))+'" data-ref="Стиль референса"><img loading="lazy" src="assets/'+item+'" alt=""><span>Использовать стиль</span></button>').join('')+'</div></section>'}
  function imageCatalog(){const groups=[['references','Референсы'],['styles','Стили'],['popular_references','Популярные референсы'],['objects','Объекты'],['tools','Инструменты']];return '<div class="catalog-head"><h2>Каталог изображений</h2><span>Листайте категории по горизонтали</span></div><div id="quickImageCatalogLanes">'+groups.map(group=>'<section class="quick-catalog-group" data-catalog-lane="'+group[0]+'"><h3>'+group[1]+'</h3><div class="quick-catalog-lane"><span class="quick-catalog-loading">Загрузка…</span></div></section>').join('')+'</div>'}
  const quickToolCatalog=[['try_on','Виртуальная примерка','assets/quick-tools/try-on.jpg'],['remove_bg','Удаление фона','assets/quick-tools/remove-background.jpg'],['replace_character','Замена персонажа','assets/quick-tools/replace-character.jpg'],['enhance','Улучшение фото','assets/quick-tools/enhance-photo.jpg'],['animate_photo','Оживление фото','assets/quick-tools/animate-photo.jpg'],['tattoo','Тату','assets/quick-tools/tattoo.jpg'],['logo','Лого','assets/quick-tools/logo-placement.jpg'],['remove_object','Удаление предмета','assets/quick-tools/remove-object.jpg'],['replace_object','Замена предмета','assets/quick-tools/replace-object.jpg']];
  async function loadQuickImageCatalog(){if(mode!=='image')return;try{const response=await fetch('/api/public/prostudio/quick-image-catalog',{cache:'default'}),data=await response.json(),catalog=data.catalog||{},hash=value=>[...String(value)].reduce((sum,char,index)=>sum+char.charCodeAt(0)*(index+7),0);for(const kind of ['references','styles','popular_references','objects']){const lane=document.querySelector('[data-catalog-lane="'+kind+'"] .quick-catalog-lane');let items=Array.isArray(catalog[kind])?catalog[kind].slice():[];if(kind==='styles'||kind==='objects')items.sort((a,b)=>(hash(a.id)%17)-(hash(b.id)%17)||hash(a.id)-hash(b.id));const hideTitle=kind==='references'||kind==='popular_references';if(lane)lane.innerHTML=items.length?items.map(item=>'<button class="reference '+(hideTitle?'no-caption':'minimal-caption')+'" data-image-catalog-kind="'+kind+'" data-image-catalog-id="'+esc(item.id)+'"><img loading="lazy" src="'+esc(item.image_url||item.url)+'" alt="'+esc(item.title||'')+'">'+(hideTitle?'':'<span>'+esc(item.title||'Открыть')+'</span>')+'</button>').join(''):'<span class="quick-catalog-loading">Раздел пока пуст</span>'}const tools=document.querySelector('[data-catalog-lane="tools"] .quick-catalog-lane');if(tools)tools.innerHTML=quickToolCatalog.map(item=>'<button class="reference" data-quick-photo-tool="'+item[0]+'"><img loading="lazy" src="'+item[2]+'" alt="'+item[1]+'"><span>'+item[1]+'</span></button>').join('')}catch(_){document.querySelectorAll('.quick-catalog-loading').forEach(item=>item.textContent='Не удалось загрузить каталог')}}
  // Manual video editor (first stage): upload files and edit them; generated
