  function videoEditorEntry(){return '<section class="ve-entry"><div><b>Видеоредактор</b><small>Загрузите видео и смонтируйте ролик: клипы, звук, переходы, текст и экспорт в MP4.</small></div><label class="ve-entry-btn"><input type="file" accept="video/*" multiple hidden data-ve-entry>Загрузить видео</label><button type="button" class="ve-entry-open" data-ve-entry-open>Открыть редактор</button></section>'}
  async function openVideoEditorOverlay(files){if(document.getElementById('veOverlay'))return;if(!document.getElementById('veStyles')){const link=document.createElement('link');link.id='veStyles';link.rel='stylesheet';link.href='css/video-editor.css?v='+VIDEO_EDITOR_VERSION;document.head.appendChild(link)}const overlay=document.createElement('div');overlay.id='veOverlay';overlay.className='ve-overlay';document.body.appendChild(overlay);document.body.style.overflow='hidden';window.parent.postMessage({source:'sylvex-knowledge',action:'workspace-cover',open:true},location.origin);const close=()=>{overlay.remove();document.body.style.overflow='';window.parent.postMessage({source:'sylvex-knowledge',action:'workspace-cover',open:false},location.origin)};try{const module=await import('./video-editor/index.js?v='+VIDEO_EDITOR_VERSION);await module.openVideoEditor({host:overlay,files:Array.from(files||[]),onClose:close})}catch(error){console.error('[video-editor]',error);overlay.innerHTML='<div class="ve-load-error"><p>Не удалось открыть видеоредактор. Обновите страницу и попробуйте ещё раз.</p><button type="button">Закрыть</button></div>';overlay.querySelector('button').onclick=close}}
  function videoCatalog(){const ids=['61','59','66','50','57','03','32','35','56','51','58','60'],groups=['Референсы','Танцы','Реклама','Анимация фотографий','Инструменты'];return '<div class="catalog-head"><h2>Каталог видео</h2><span>Сцены, камера и движение</span></div>'+groups.map((name,index)=>catalogLane(name,ids.filter((_,i)=>i%groups.length===index).concat(ids.slice(index,index+2)),'video')).join('')}
  let musicSlides=[{1:'Pop',cover:'assets/hero-ai/suno.jpg',title:'Pop & Vocal',genre:'Pop'},{1:'Ambient',cover:'assets/hero-ai/gemini.jpg',title:'Ambient',genre:'Ambient'},{1:'Cinematic',cover:'assets/hero-ai/seedream.jpg',title:'Cinematic',genre:'Cinematic'},{1:'Hip-Hop',cover:'assets/hero-ai/grok.jpg',title:'Hip-Hop',genre:'Hip-Hop'},{1:'Electronic',cover:'assets/knowledge-center/music.png',title:'Electronic',genre:'Electronic'}];
  function musicStage(){return '<section class="music-stage" id="musicStage"><button class="music-nav prev" data-slide="-1">‹</button>'+musicSlides.map((track,i)=>'<button class="music-card'+(track.pending?' is-generating':'')+'" data-index="'+i+'" data-ref="'+esc(track.genre||track.title)+'"'+(track.audioUrl?' data-audio="'+esc(track.audioUrl)+'"':'')+(track.pending?' aria-busy="true"':'')+'><img src="'+esc(track.cover||'assets/knowledge-center/music.png')+'" alt="">'+(track.pending?'<i class="qm-loader" aria-hidden="true"></i>':'')+'<span>'+esc(track.title)+'</span></button>').join('')+'<button class="music-nav next" data-slide="1">›</button></section>'}
  function player(){return '<div class="player quick-player" id="quickMusicPlayer"><div class="quick-player-glass"><span class="quick-player-cover"><img id="quickPlayerCover" alt="" hidden><i>S</i></span><div class="quick-player-body"><b id="quickPlayerTitle">Выберите трек</b><div class="quick-player-timeline"><time id="quickPlayerTime">00:00</time><input id="quickPlayerSeek" type="range" min="0" max="100" value="0" step="0.1" aria-label="Позиция трека"><time id="quickPlayerDuration">00:00</time></div><div class="quick-player-actions"><button type="button" data-track-repeat aria-label="Повтор">↻</button><button type="button" data-track-step="-1" aria-label="Предыдущий">◀</button><button class="quick-player-main" type="button" data-track-play aria-label="Воспроизвести">▶</button><button type="button" data-track-step="1" aria-label="Следующий">▶</button><button type="button" data-track-shuffle aria-label="Перемешать">⌁</button></div></div></div><audio id="quickPlayerAudio" preload="metadata"></audio></div>'}
  function dialogues(){const cards=[['Рекламный диалог','— Попробуем новый формат?','— Да, запускай генерацию.'],['Подкаст','— Что изменит ИИ?','— Скорость воплощения идей.'],['Сцена фильма','— Ты слышал это?','— Нам пора уходить.']];return '<div class="catalog-head"><h2>Примеры диалогов</h2><span>Выберите структуру</span></div><section class="dialogues">'+cards.map(x=>'<article class="dialogue-card" data-ref="'+x.slice(1).join('\n')+'"><b>'+x[0]+'</b><div class="bubble">'+x[1]+'</div><div class="bubble me">'+x[2]+'</div></article>').join('')+'</section>'+player()}
  function render(){if(mode==='general'){root.innerHTML='<section class="studio-launch"><div><img src="assets/logo.png" alt="SYLVEX"><h1>ProStudio</h1><p>Все модели и профессиональные инструменты SYLVEX в едином рабочем пространстве.</p><button data-generate>Открыть ProStudio</button></div></section>';return}const cfg=data[mode]||data.image;if(mode==='text'){root.innerHTML='<div class="text-page"><button class="qt-menu-btn" type="button" data-qt-menu aria-label="История чатов"><span></span><span></span><span></span></button><div class="quick-text-chat" id="quickTextChat"></div>'+generator(cfg)+'</div>'+quickTextDrawer();return}if(mode==='voice'){if(window.SylvexQuickVoice)window.SylvexQuickVoice.mount(root);return}root.innerHTML=(mode==='music'?quickMusicDrawer():'')+head(cfg)+(mode==='music'?musicStage():'')+(mode==='image'?imageGenerator(cfg):generator(cfg))+(mode==='video'?videoEditorEntry():'')+(mode==='image'?imageCatalog():mode==='video'?videoCatalog():player());if(mode==='music'){updateSlides(0);bindMusicGestures()}}
  let activeSlide=0;function updateSlides(delta){activeSlide=(activeSlide+delta+musicSlides.length)%musicSlides.length;document.querySelectorAll('.music-card').forEach(card=>{let p=Number(card.dataset.index)-activeSlide;if(p>musicSlides.length/2)p-=musicSlides.length;if(p<-musicSlides.length/2)p+=musicSlides.length;card.classList.toggle('is-hidden',Math.abs(p)>2);card.dataset.pos=String(p)})}
  function bindMusicGestures(){const stage=document.getElementById('musicStage');if(!stage)return;let startX=0;stage.addEventListener('pointerdown',e=>{startX=e.clientX;stage.setPointerCapture&&stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointerup',e=>{const dx=e.clientX-startX;if(Math.abs(dx)>35)updateSlides(dx<0?1:-1)});stage.addEventListener('wheel',e=>{if(Math.abs(e.deltaX)>8||Math.abs(e.deltaY)>18){e.preventDefault();updateSlides((e.deltaX||e.deltaY)>0?1:-1)}},{passive:false})}
  function loadMusicSlides(tracks){
    const available=(Array.isArray(tracks)?tracks:[]).filter(track=>track&&track.audioUrl).map(track=>({
      1:track.genre||track.title||'Music',
      id:String(track.id||track.audioUrl),
      title:String(track.title||'Трек Suno'),
      genre:String(track.genre||''),
      cover:String(track.coverUrl||'assets/knowledge-center/music.png'),
      audioUrl:String(track.audioUrl)
    }));
    musicHistory=available;renderQuickMusicHistory();
    if(!available.length)return;
    musicSlides=musicSlides.filter(track=>track.pending).concat(available);
    activeSlide=0;
    const stage=document.getElementById('musicStage');
    if(stage){stage.outerHTML=musicStage();updateSlides(0);bindMusicGestures();playQuickMusic(0,false)}
  }
  function playQuickMusic(index,forcePlay){
    if(!musicSlides.length)return;
    activeSlide=(Number(index)+musicSlides.length)%musicSlides.length;
    updateSlides(0);
    const track=musicSlides[activeSlide],audio=document.getElementById('quickPlayerAudio'),button=document.querySelector('[data-track-play]');
    if(!track)return;
    const title=document.getElementById('quickPlayerTitle');if(title)title.textContent=track.title;
    const cover=document.getElementById('quickPlayerCover');if(cover){cover.src=track.cover;cover.hidden=false}
    const player=document.getElementById('quickMusicPlayer');if(player)player.style.setProperty('--track-cover','url('+JSON.stringify(track.cover)+')');
    if(!audio||!track.audioUrl)return;
    if(audio.src!==new URL(track.audioUrl,location.href).href)audio.src=track.audioUrl;
    if(forcePlay){audio.play().then(()=>{if(button)button.textContent='❚❚'}).catch(()=>{})}
  }
  function quickAudioTime(seconds){const value=Number.isFinite(seconds)?Math.max(0,Math.floor(seconds)):0;return Math.floor(value/60)+':'+String(value%60).padStart(2,'0')}
  function showMedia(src){selectedMedia=src;const box=document.getElementById('mediaPreview');if(!box)return;box.hidden=false;box.querySelector('img').src=src}
  function updatePhotoGenerate(){const prompt=document.getElementById('knowledgePrompt'),button=document.querySelector('.photo-generate');if(button)button.disabled=!(prompt&&prompt.value.trim())&&!(mode==='text'&&qtFile)}
  function currentOptions(){const values={};document.querySelectorAll('[data-control-value]').forEach(input=>{values[input.dataset.controlValue]=input.value});const ratio=document.getElementById('knowledgeRatio');if(ratio)values.ratio=ratio.value;return values}
