  function toggleQuickTextMic(){if(qtRecognition){qtRecognition.stop();return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){quickTextNotice('Голосовой ввод не поддерживается на этом устройстве или в браузере');return}const recognition=new Recognition();qtRecognition=recognition;recognition.lang=(navigator.language||'ru-RU');recognition.interimResults=false;recognition.continuous=false;recognition.onresult=event=>{const text=Array.from(event.results).map(r=>r[0]&&r[0].transcript||'').join(' ');quickTextInsert(text)};recognition.onerror=event=>{if(event.error==='not-allowed'||event.error==='service-not-allowed')quickTextNotice('Разрешите доступ к микрофону');else if(event.error==='network'||event.error==='language-not-supported')quickTextNotice('Голосовой ввод сейчас недоступен на этом устройстве')};recognition.onend=()=>{qtRecognition=null;setMicState(false)};try{recognition.start();setMicState(true)}catch(_){qtRecognition=null;setMicState(false);quickTextNotice('Голосовой ввод не поддерживается на этом устройстве или в браузере')}}
