  function qmApplyCapabilities(){const model=qmSelectedModel(),supports=qmModelSupportsReference(model),row=document.getElementById('qmRefRow');if(row)row.hidden=!supports;const duration=document.querySelector('[data-picker="duration"]');if(duration)duration.closest('.photo-picker').hidden=!qmModelHasDuration(model);if(!supports&&qmReference){qmClearReference();quickTextNotice('Аудио-референс убран: эта модель его не поддерживает')}}
  function qmClearReference(){qmReference=null;const chip=document.getElementById('qmRefChip'),add=document.querySelector('[data-qm-ref-add]'),input=document.getElementById('qmRefFile');if(chip){chip.hidden=true;chip.innerHTML=''}if(add)add.hidden=false;if(input)input.value=''}
  function qmShowReference(){const chip=document.getElementById('qmRefChip'),add=document.querySelector('[data-qm-ref-add]');if(!chip||!qmReference)return;chip.innerHTML='<span>🎵 '+esc(qmReference.file.name||'reference')+' · '+Math.max(1,Math.round(qmReference.durationMs/1000))+' сек</span><button type="button" data-qm-ref-remove aria-label="Убрать референс">×</button>';chip.hidden=false;if(add)add.hidden=true}
  function qmAudioDuration(file){return new Promise(resolve=>{const audio=document.createElement('audio'),url=URL.createObjectURL(file);let done=false;const finish=value=>{if(done)return;done=true;URL.revokeObjectURL(url);resolve(value)};audio.preload='metadata';audio.onloadedmetadata=()=>finish(Number.isFinite(audio.duration)?audio.duration*1000:0);audio.onerror=()=>finish(0);setTimeout(()=>finish(0),8000);audio.src=url})}
  async function qmPickReference(file){if(!file)return;if(!String(file.type||'').startsWith('audio/')&&!/\.(mp3|wav|m4a|aac|ogg|oga|flac|aiff?|webm)$/i.test(file.name||'')){quickTextNotice('Выберите аудиофайл');return}if(file.size>8*1024*1024){quickTextNotice('Референс должен быть не больше 8 МБ');return}const durationMs=await qmAudioDuration(file);if(!durationMs){quickTextNotice('Не удалось прочитать аудиофайл');return}if(durationMs>30500){quickTextNotice('Референс должен быть не длиннее 30 секунд');const input=document.getElementById('qmRefFile');if(input)input.value='';return}qmReference={file,durationMs:Math.min(30000,Math.round(durationMs))};qmShowReference()}
  function renderQuickMusicUser(){const card=document.getElementById('qmUser'),u=qmUserCard;if(!card||!u)return;const avatar=qmSafeUrl(u.avatar);card.innerHTML='<i>'+(avatar?'<img src="'+esc(avatar)+'" alt="">':esc(u.initials||'S'))+'</i><span><b>'+esc(u.name)+'</b><small>'+esc(u.handle)+'</small></span>'+(u.balance!==null&&u.balance!==undefined?'<em>'+Number(u.balance).toLocaleString()+' ⚡️</em>':'')}
