  function qmFinishRename(input,save){const index=Number(input.dataset.qmRenameInput),title=input.value.trim();qmRenaming=-1;if(save&&title&&musicHistory[index]&&title!==musicHistory[index].title){musicHistory[index].title=title;qmTrackPost('rename',index,{title})}renderQuickMusicHistory()}
