    const download=target.closest('[data-qm-download]');if(download){qmTrackPost('download',Number(download.dataset.qmDownload));qmMenuFor=-1;renderQuickMusicHistory();return}
    const del=target.closest('[data-qm-delete]');if(del){const i=Number(del.dataset.qmDelete);if(qmConfirmDelete!==i){qmConfirmDelete=i;renderQuickMusicHistory();return}qmTrackPost('delete',i);musicHistory.splice(i,1);qmConfirmDelete=-1;qmMenuFor=-1;renderQuickMusicHistory();return}
