  function openStudio(){const prompt=document.getElementById('knowledgePrompt');if(mode!=='general'&&!(prompt&&prompt.value.trim())&&!(mode==='text'&&qtFile))return;const model=document.getElementById('knowledgeModel'),textValue=prompt?prompt.value.trim():'';if(mode==='text'){if(quickTextSend(textValue,model?model.value:'')){prompt.value='';updatePhotoGenerate()}return}if(mode==='music'){quickMusicGenerate(textValue,model?model.value:'',currentOptions());prompt.value='';updatePhotoGenerate();return}window.parent.postMessage({source:'sylvex-knowledge',action:mode==='text'?'text-chat':'generate',mode,prompt:textValue,model:model?model.value:'',reference:selectedMedia,style:selectedStyle,options:currentOptions()},location.origin)}
