  document.addEventListener('click',event=>{
    if(mode!=='music')return;
    const card=event.target.closest('.music-card');
    if(card){event.preventDefault();event.stopImmediatePropagation();playQuickMusic(Number(card.dataset.index),!!card.dataset.audio);return}
    const step=event.target.closest('[data-track-step]');
    if(step){playQuickMusic(activeSlide+Number(step.dataset.trackStep),true);return}
    const play=event.target.closest('[data-track-play]');
    if(play){const audio=document.getElementById('quickPlayerAudio');if(!audio)return;if(!audio.src){playQuickMusic(activeSlide,true);return}if(audio.paused){audio.play().then(()=>play.textContent='❚❚').catch(()=>{})}else{audio.pause();play.textContent='▶'}return}
    const repeat=event.target.closest('[data-track-repeat]');if(repeat){const audio=document.getElementById('quickPlayerAudio');if(audio){audio.loop=!audio.loop;repeat.classList.toggle('is-active',audio.loop)}return}
    const shuffle=event.target.closest('[data-track-shuffle]');if(shuffle){shuffle.classList.toggle('is-active');return}
  },true);
  document.addEventListener('change',e=>{if(e.target.id==='knowledgeFile'&&e.target.files&&e.target.files[0]){const reader=new FileReader();reader.onload=()=>showMedia(String(reader.result||''));reader.readAsDataURL(e.target.files[0])}if(e.target.dataset.control==='genre'){const index=musicSlides.findIndex(x=>x[1].toLowerCase().startsWith(e.target.value.toLowerCase()));if(index>=0){activeSlide=index;updateSlides(0)}}});
  document.addEventListener('click',e=>{const mic=e.target.closest('.quick-mic');if(mic){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return;const recognition=new Recognition();recognition.lang='ru-RU';recognition.interimResults=false;recognition.onstart=()=>mic.classList.add('listening');recognition.onend=()=>mic.classList.remove('listening');recognition.onresult=result=>{const field=document.getElementById('knowledgePrompt');if(field){field.value=(field.value+' '+result.results[0][0].transcript).trim();field.dispatchEvent(new Event('input'))}};recognition.start();return}const picker=e.target.closest('[data-picker]');if(picker){const name=picker.dataset.picker,menu=document.querySelector('[data-menu="'+name+'"]'),willOpen=menu&&menu.hidden;closePhotoMenus();if(menu&&willOpen){menu.hidden=false;picker.setAttribute('aria-expanded','true')}return}const modelChoice=e.target.closest('[data-model]');if(modelChoice){const picker=modelChoice.closest('.photo-picker'),id=modelChoice.dataset.model;document.getElementById('knowledgeModel').value=id;picker.querySelector('.photo-picker-trigger').innerHTML='<b>'+esc(modelChoice.dataset.label)+'</b><i>⌄</i>';picker.querySelectorAll('[data-model]').forEach(x=>x.classList.toggle('is-selected',x===modelChoice));closePhotoMenus();return}const ratioChoice=e.target.closest('[data-ratio]');if(ratioChoice){const picker=ratioChoice.closest('.photo-picker'),value=ratioChoice.dataset.ratio,input=picker.querySelector('input');if(input)input.value=value;picker.querySelector('.photo-picker-trigger').innerHTML=ratioIcon(value)+'<b>'+value+'</b><i>⌄</i>';picker.querySelectorAll('[data-ratio]').forEach(x=>x.classList.toggle('is-selected',x===ratioChoice));closePhotoMenus();return}const quickChoice=e.target.closest('[data-quick-option]');if(quickChoice){const picker=quickChoice.closest('.photo-picker'),value=quickChoice.dataset.quickOption,input=picker.querySelector('input');if(input)input.value=value;picker.querySelector('.photo-picker-trigger').innerHTML='<b>'+esc(quickChoice.dataset.label)+'</b><i>⌄</i>';picker.querySelectorAll('[data-quick-option]').forEach(x=>x.classList.toggle('is-selected',x===quickChoice));if(quickChoice.dataset.controlName==='genre'){const index=musicSlides.findIndex(x=>x[1].toLowerCase().startsWith(String(value).toLowerCase()));if(index>=0){activeSlide=index;updateSlides(0)}}const cast=document.querySelector('[data-cast="'+quickChoice.dataset.controlName+'"]');if(cast)cast.innerHTML='<b>'+quickChoice.dataset.controlName.replace('speaker','')+'</b> '+esc(quickChoice.dataset.label);closePhotoMenus();return}if(!e.target.closest('.photo-picker'))closePhotoMenus();if(e.target.closest('[data-add-file]')){document.getElementById('knowledgeFile').click();return}if(e.target.closest('[data-remove-media]')){selectedMedia='';qtFile=null;document.getElementById('mediaPreview').hidden=true;updatePhotoGenerate();return}const slide=e.target.closest('[data-slide]');if(slide){updateSlides(Number(slide.dataset.slide));return}const card=e.target.closest('[data-ref]');if(card){if(mode==='video'){window.parent.postMessage({source:'sylvex-knowledge',action:'video-template',templateId:card.dataset.templateId||''},location.origin);return}const src=card.querySelector('img')&&card.querySelector('img').src;if(src)showMedia(src);const prompt=document.getElementById('knowledgePrompt');if(prompt&&mode==='voice'){prompt.value=card.dataset.ref||'';prompt.focus();prompt.dispatchEvent(new Event('input'))}if(card.classList.contains('music-card')){activeSlide=Number(card.dataset.index);updateSlides(0)}return}if(e.target.closest('[data-generate]'))openStudio()});
  render();
